import { writeFile, mkdir } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");

const C = (category, title, idea, clues, plan, counter, mistake, mantra, question, answer, diagram, marks) => ({
  category, title, idea, clues: clues.split("|"), plan, counter, mistake, mantra, question, answer, diagram, marks: marks.split(" ").filter(Boolean)
});

// Fifty durable positional ideas. Each returns once in every learning pass.
const concepts = [
  C("Foundations", "Material balance", "Material is the baseline of an evaluation, not the verdict. Equal pieces can have very unequal usefulness.", "Count each side once|Notice trapped or loose pieces|Compare what the pieces can actually do", "Improve the least useful piece before hunting for more material.", "The opponent may use activity or king safety as compensation.", "Recounting material while ignoring activity.", "Count the pieces; judge the jobs.", "Both sides have equal material. Must the position be equal?", "No. Activity, king safety, space, structure, and initiative can outweigh a nominally even count.", "fundamentals", "d4 e4 d5 e5"),
  C("Foundations", "Piece activity", "An active piece has useful squares, targets, and influence. Activity is practical value in motion.", "Number of useful legal moves|Access to the enemy camp|Whether a piece attacks and defends at once", "Give the least active piece a route toward a useful square.", "Forcing moves can punish a slow improvement.", "Calling a piece active merely because it is advanced.", "Useful squares, not forward squares.", "Which is more active: a centralized knight with no target, or a rook controlling an open file?", "Usually the rook: activity is measured by useful influence, not by closeness to the center alone.", "fundamentals", "c3 f3 c6 f6 d4 d5"),
  C("Foundations", "Static and dynamic advantages", "Static advantages tend to last; dynamic advantages must be used before they fade.", "Permanent pawn weaknesses|Temporary lead in development|Open king or fleeting initiative", "When the edge is static, improve patiently; when it is dynamic, act with energy.", "The opponent wants to trade away momentum or repair the lasting weakness.", "Playing slowly with a temporary edge, or rushing with a permanent one.", "Permanent: prepare. Temporary: press.", "You have a lead in development but no lasting pawn target. Should you drift?", "No. Development is a dynamic edge; seek open lines or forcing play before the opponent catches up.", "dynamic", "e4 d5 f7 e8"),
  C("Foundations", "Imbalances", "A position becomes understandable when you name what differs: bishops, space, structure, files, safety, or time.", "One side owns a bishop pair|The pawn structures are asymmetric|A file or color complex belongs to one side", "Choose a plan that makes your favorable imbalance matter.", "The opponent will steer play toward a different imbalance.", "Making a generic move before naming what is different.", "Difference first, plan second.", "You have the bishop pair; your opponent has an outpost. Which feature should guide the plan?", "Whichever can be made relevant sooner. Open the position for the bishops while questioning the outpost.", "dynamic", "c1 g2 c6 f6 d4 e5"),
  C("Foundations", "Tempo and urgency", "A tempo matters when the position contains a race, a break, or a threat. Not every position rewards speed equally.", "Uncastled kings|A pawn break ready now|A passed pawn or attack racing forward", "Ask what changes if both sides receive one free move.", "The opponent may create a threat that changes your move order.", "Playing an improving move without checking whether now is a critical moment.", "Before a slow move, give them a move.", "If you pass, the opponent plays a freeing break. Is your quiet improvement still sensible?", "Probably not. Prevent, answer, or exploit the break before spending a tempo elsewhere.", "dynamic", "c5 d4 e5 f4"),

  C("Center & Space", "Central control", "The center is valuable because pieces use it to switch wings and because central breaks open many lines at once.", "Pawns controlling d4, d5, e4, e5|Pieces that can enter central squares|Pressure on a central pawn", "Strengthen control, challenge the opponent's center, or use it as a highway.", "A wing attack may make central control urgent.", "Occupying the center with a piece that can be chased by tempo.", "Control the center; occupy it only when safe.", "Do you need a pawn on a central square to control it?", "No. Pieces and pawns can control a square from afar; control matters more than occupation.", "center", "d4 e4 d5 e5"),
  C("Center & Space", "Pawn center", "Central pawns gain space and restrict pieces, but they can also become targets that need support.", "Connected pawns on d4 and e4|Enemy pressure on their base|A possible central lever", "Support the center, advance it with purpose, or trade it for activity.", "The opponent will blockade or undermine its base.", "Pushing both pawns simply because they look impressive.", "A center is strong while it can move or be defended.", "Your broad pawn center is fixed and blockaded. Is it still automatically an advantage?", "No. A fixed center can become a pair of targets. Prepare a break or activate pieces behind it.", "pawn-center", "d4 e4 d5 e5"),
  C("Center & Space", "Space advantage", "More space gives your pieces more room and leaves the opponent fewer comfortable squares.", "Advanced safe pawns|Restricted enemy pieces|Room to switch the attack", "Improve behind the space, avoid needless trades, then create a second front.", "The cramped side seeks exchanges and pawn breaks.", "Advancing again before the pieces are ready behind the pawns.", "Space needs pieces behind it.", "With more space, should you exchange pieces automatically?", "Usually no. Keeping pieces preserves the opponent's congestion, though a favorable specific trade can still help.", "space", "c5 d5 e5 f5"),
  C("Center & Space", "Pawn breaks", "A pawn break changes the map: it opens lines, challenges a chain, or creates a passer.", "Pawn contact is possible|Your pieces face the future open lines|The opponent cannot answer comfortably", "Prepare the break by placing pieces where the resulting lines will matter.", "The opponent may close, capture, bypass, or counterbreak.", "Playing the break because it is thematic without calculating the new structure.", "Prepare the line that the break will open.", "What should you inspect before playing a thematic pawn break?", "All captures, advances, and counterbreaks, plus which pieces benefit from every resulting open line.", "break", "c5 d4 e5 f4"),
  C("Center & Space", "Cramped positions", "A cramped side has too few useful squares. Its first goal is freedom, not immediate conquest.", "Pieces blocking one another|Few safe developing squares|A break that could trade space", "Rearrange without creating targets, trade a piece, and prepare the freeing break.", "The spacious side wants to prevent the break and keep pieces on.", "Lashing out with an unprepared pawn move that creates new weaknesses.", "When cramped, trade space or trade a piece.", "What is often a useful exchange for the cramped side?", "Exchanging one pair of pieces, because every remaining piece then has more room.", "cramped", "c6 d6 e6 f6"),

  C("Pawn Structure", "Pawn islands", "Each disconnected pawn group is an island. More islands usually mean more bases to defend in an endgame.", "Gaps between pawn groups|Fixed pawn bases|Rooks able to attack from the side", "Keep pieces active and avoid creating another isolated group.", "The opponent will trade pieces and attack the separate bases.", "Counting islands as a verdict while ignoring activity.", "Islands are targets only when pieces can reach them.", "Are three pawn islands always losing against two?", "No. They are a lasting concern, but activity, passed pawns, and king position decide whether they can be attacked.", "islands", "a2 c3 f2 h2 a7 b7 e6 g7 h7"),
  C("Pawn Structure", "Isolated queen's pawn", "An isolated d-pawn grants space and active squares but lacks a neighboring pawn defender.", "Open c- and e-files|The d5 outpost|A possible d4-d5 break", "Use activity and the central break before the pawn becomes a fixed endgame target.", "The defender blockades, exchanges pieces, and attacks the pawn.", "Defending the pawn passively until all activity disappears.", "The IQP is an energy source before it is a target.", "What trade usually helps the side playing against an IQP?", "Exchanging pieces, especially active attackers, because the isolated pawn is harder to defend in a quieter position.", "iqp", "d4 d5 c4 e4 c5 e5"),
  C("Pawn Structure", "Backward pawn", "A backward pawn cannot safely advance and sits behind its neighbors, often on a semi-open file.", "No friendly pawn can support its advance|The square ahead is controlled|An enemy rook can face it", "Defend actively, prepare its advance, or gain counterplay elsewhere.", "The opponent will blockade the square in front, then pile up.", "Protecting the pawn with every piece and becoming tied down.", "Attack the blockader or free the pawn.", "Which square is often as important as a backward pawn itself?", "The square directly in front of it, because a secure blockader there fixes the weakness.", "backward", "d6 d5 c5 e5 d7"),
  C("Pawn Structure", "Doubled pawns", "Doubled pawns may be weak, but they can also open files, control key squares, and provide dynamic compensation.", "Two friendly pawns on one file|A newly opened neighboring file|Extra control over central squares", "Use the open line or square control before accepting a passive defense.", "The opponent will blockade the front pawn and attack the rear one.", "Labeling doubled pawns bad without asking what the capture opened.", "Structure has costs and receipts.", "When can doubled pawns be useful?", "When they open a file, strengthen central control, or give active piece play that outweighs their endgame weakness.", "doubled", "c2 c3 b2 d2 c4"),
  C("Pawn Structure", "Passed pawn", "A passed pawn has no enemy pawn on its file or adjacent files to stop its advance.", "Clear neighboring files|A safe route forward|Pieces available to support or blockade", "Advance when it gains something, but improve the supporting pieces first when needed.", "The defender blockades from the front and attacks the base.", "Pushing automatically and allowing a perfect blockade.", "Passers must be pushed—with support and timing.", "Where is the ideal blockading square against a passed pawn?", "Directly in front of it, where the blockader cannot be chased by that pawn.", "passer", "d5 d6 c7 e7"),
  C("Pawn Structure", "Protected passed pawn", "A protected passer is defended by another pawn and can tie down enemy pieces for a long time.", "A passer guarded by a neighboring pawn|A stable advance square|The enemy king kept away", "Fix the defender, improve the king, and use the passer as a distraction.", "The defender seeks to sacrifice or undermine the supporting pawn.", "Rushing the passer when its mere existence already restricts the opponent.", "A protected passer can win without moving.", "Why might you leave a protected passer in place?", "It can control key squares and tie down a blockader while your king or pieces attack elsewhere.", "protected", "d5 e4 d6 e5"),
  C("Pawn Structure", "Pawn majority", "A pawn majority can create a passed pawn, but only if the structure and kings allow the advance.", "Three pawns against two on a wing|A healthy lever|The enemy king's distance", "Use the majority to create a passer while preventing counterplay on the other wing.", "The minority may fix your pawns or create a weakness before you advance.", "Pushing the majority without choosing the correct pawn order.", "A majority is potential, not yet a passer.", "What is the main purpose of a wing majority in an endgame?", "To create a passed pawn, often forcing the enemy king or pieces into passive defense.", "majority", "f2 g2 h2 f7 g7"),
  C("Pawn Structure", "Pawn chain", "A pawn chain points toward space; its base is usually the easiest point to attack.", "Diagonally connected pawns|A fixed base|Flank space in the direction of the chain", "Attack on the side your chain points toward and protect or move its base.", "The opponent undermines the base with a pawn lever.", "Attacking the head of a chain when the base is much easier to reach.", "The arrow shows the wing; the base shows the target.", "Where do you normally attack an enemy pawn chain?", "At its base, because that pawn lacks support from another pawn in the chain.", "chain", "c3 d4 e5 f6 c6 d5 e4"),
  C("Pawn Structure", "Pawn tension", "When pawns can capture each other, the unresolved tension preserves options and constrains both sides.", "Two pawns in contact|Several possible recaptures|Files that would open after exchange", "Keep tension when it limits the opponent; release it when the resulting structure favors you.", "The opponent may resolve tension at a moment that improves their pieces.", "Capturing automatically just to make the position simpler.", "Do not release tension without collecting something.", "What question should precede a pawn capture that releases tension?", "Who benefits from the new file, square, or pawn structure after every likely recapture?","tension", "c4 d5 e4 f5"),
  C("Squares & Lines", "Weak square", "A square is weak when a pawn cannot defend it and an enemy piece can realistically use it.", "No pawn can challenge an occupier|A stable route reaches the square|The square touches useful targets", "Occupy it with a suitable piece or use the threat of occupation to provoke concessions.", "The defender trades the occupier or contests the route.", "Calling every pawn-undefended square weak even when nobody can use it.", "A weak square needs a visitor.", "Is a hole on a1 strategically important by itself?", "Usually not. A weakness matters only if it can be reached and used for a useful purpose.", "lines", "d5 e6 c6"),
  C("Squares & Lines", "Outpost", "An outpost is a protected advanced square where a piece cannot be chased by an enemy pawn.", "Pawn support for the square|No enemy pawn lever|Targets or routes from the square", "Install the piece whose influence grows most there, then avoid exchanging it cheaply.", "The defender contests the supporting pawn or trades the occupant.", "Occupying an outpost with the wrong piece simply because the square is available.", "An outpost is a job site, not a trophy.", "What makes an outpost more valuable than a merely safe square?", "From it, the piece attacks targets, restricts the enemy, or supports entry into the position.", "lines", "d5 c4 e4 c6 e6"),
  C("Squares & Lines", "Open file", "An open file has no pawns. Rooks use it as an entry road, not as an ornament.", "No pawns on the file|An invasion square|A target on the far end", "Contest the file, double rooks if useful, and fight for the entry square.", "The opponent may trade rooks or control the entry square.", "Owning a file that leads nowhere while another part of the board burns.", "A file matters at its destination.", "You control an open file but cannot enter on the seventh or eighth rank. What next?", "Create or control an entry square; mere file possession may have little value without penetration.", "lines", "d1 d7 d2 d8"),
  C("Squares & Lines", "Semi-open file", "A semi-open file has no friendly pawn but still contains an enemy pawn, making that pawn a natural target.", "Your rook faces an enemy pawn|No friendly pawn blocks the file|Pressure can be increased", "Place a rook on the file and combine pressure with another weakness or break.", "The defender advances, protects, or trades the target pawn.", "Piling up on a pawn that can easily move away.", "A semi-open file points at a pawn—check whether it is fixed.", "What is the usual target on a semi-open file?", "The opponent's pawn on that file, especially when it cannot safely advance.", "lines", "c1 c7 c2 c8"),
  C("Squares & Lines", "Seventh rank", "A rook on the seventh rank attacks pawns from the side and often restricts the enemy king.", "Enemy pawns still on their second rank|A safe entry square|The king cut off", "Enter, attack several pawns laterally, and consider doubling rooks.", "The defender activates a rook behind you or forces a trade.", "Grabbing one pawn and letting the rook become trapped.", "Enter with an exit.", "Why is a rook on the seventh often stronger than a rook attacking from the front?", "It attacks multiple pawn bases sideways and can confine the king at the same time.", "seventh", "d7 a7 b7 f7 g7 g8"),
  C("Squares & Lines", "Open diagonal", "A bishop needs an open diagonal with a destination. Long range is useful only when the line touches something important.", "Pawns blocking your bishop|A lever that opens the diagonal|Targets on the same color", "Clear the diagonal by moving, exchanging, or sacrificing the blocking pawn when justified.", "The opponent closes the diagonal or trades the bishop.", "Admiring a long diagonal with no target at its end.", "Trace the diagonal all the way to its target.", "What should you ask before investing a move to open a bishop's diagonal?", "What concrete target, entry square, or defensive task will the bishop gain after the line opens?","lines", "b1 c2 d3 e4 f5 g6 h7"),

  C("Piece Quality", "Worst piece", "A quiet position often improves most when you find the piece contributing least and give it a useful job.", "A piece with few useful moves|Duplicated defensive duties|A piece blocked by its own pawns", "Give the piece a route, a target, or a useful exchange.", "The opponent may create urgency before your maneuver finishes.", "Improving an already excellent piece because its move looks attractive.", "Ask the least useful piece what it needs.", "Why is improving the worst piece such a reliable default?", "It raises the coordination of the whole army without requiring the position to contain an immediate target.", "pieces", "a1 c1 b1 f1 d2"),
  C("Piece Quality", "Knight versus bishop", "Knights thrive on stable squares and closed structures; bishops thrive on open lines and play on both wings.", "Number of pawns on both flanks|Stable central squares|Whether the position can open", "Shape the pawn structure for your minor piece and deny the opponent's ideal terrain.", "The opponent will transform the structure to favor the other piece.", "Using the slogan 'bishop good, knight bad' without reading the pawn map.", "Judge the terrain, then judge the piece.", "Which piece often improves when pawns are fixed on both wings and the position opens?", "The bishop, because it can switch wings quickly while the knight needs several moves.", "pieces", "c3 f6 d4 e5 c5 f4"),
  C("Piece Quality", "Good and bad bishop", "A bishop is limited when its own pawns sit on its color, but it can still defend them or escape outside the chain.", "Many friendly pawns on one color|A route outside the chain|Targets on the bishop's color", "Move the pawns, exchange the bishop, or bring it outside the chain before fixing the structure.", "The opponent tries to keep the bishop biting granite.", "Calling a bishop bad and giving up on improving it.", "A bad bishop needs a door, a trade, or a job.", "Can a 'bad' bishop still be valuable?", "Yes. It may defend key pawns, support a break, or become active outside its pawn chain.", "bishops", "c1 d2 e3 f4 b2 d4 f2"),
  C("Piece Quality", "Bishop pair", "Two bishops cover both color complexes and become stronger as the board opens.", "Open or openable center|Targets on both colors|Play on both wings", "Preserve both bishops when the position can open, and use pawn breaks to create lines.", "The opponent seeks a blockade, a knight outpost, or an exchange of one bishop.", "Keeping the pair at all costs when one bishop has no future.", "The pair is potential; open lines cash it in.", "What structural change usually helps the bishop pair?", "Pawn exchanges that open the center and create play on both sides of the board.", "bishops", "c3 f3 c6 f6 d4 e5"),
  C("Piece Quality", "Knight centralization", "A knight near the center influences more squares and reaches both wings faster.", "A safe central route|Enemy pawns unable to chase it|Useful targets from the destination", "Reroute the knight through stable squares rather than jumping forward without support.", "The opponent may deny the route or force the knight to the rim.", "Centralizing onto a square where a pawn gains tempo by chasing it.", "A knight wants a stable center, not a temporary view.", "Why is a centralized knight especially valuable in a closed position?", "Its short-range jumps ignore blocked lines and can attack behind the pawn chains.", "pieces", "d4 e5 c3 f6 a3 h6"),
  C("Piece Quality", "Rook activity", "Rooks need open lines, entry squares, and freedom from passive pawn defense.", "Open or semi-open files|A rank for lateral attack|A chance to get behind a passer", "Activate the rook even at the cost of a pawn when the resulting activity is sufficient.", "The opponent cuts the rook off or forces it into passive defense.", "Keeping a rook tied to a pawn that the king could defend.", "Rooks belong on roads and behind passers.", "Where do rooks usually belong relative to a passed pawn?", "Behind it—whether the pawn is yours or the opponent's—because the rook gains range as the pawn moves.", "pieces", "a1 d1 d7 h7 a8"),
  C("Piece Quality", "Queen placement", "The queen is powerful but vulnerable to tempo. Its best square often supports rather than leads.", "Enemy pieces can attack it|Several jobs from one safe square|Open lines near either king", "Place the queen where it coordinates threats without becoming the target of development.", "The opponent gains tempi by attacking it or offers a useful queen trade.", "Sending the queen forward before the minor pieces are ready.", "Let the queen join the attack, not start the traffic jam.", "Why can an early advanced queen reduce your activity?", "Enemy pieces develop with tempo against it while your own pieces remain blocked or undeveloped.", "pieces", "d1 h5 c6 f6 e7"),
  C("Piece Quality", "King activity", "In an endgame, the king changes from a protected piece into a powerful short-range attacker and blocker.", "Few mating threats remain|A route toward the center|Pawn races decided by king distance", "Centralize the king before starting a pawn race.", "The opposing king seeks opposition or entry on the same route.", "Leaving the king passive because king safety habits survived the queen trade.", "When queens leave, invite the king in.", "What usually happens to king value after queens and many pieces are exchanged?", "It rises sharply; centralization and opposition often become the main positional factors.", "endgame", "e4 e6 d5 f5"),
  C("Piece Quality", "Piece coordination", "Coordinated pieces attack, defend, and make threats together. One strong piece alone is often only a target.", "Several pieces touch the same target|Pieces protect one another|Moves improve more than one piece", "Arrange pieces so each move adds a second attacker, defender, or route.", "The opponent breaks the connection or trades a key coordinator.", "Counting attackers without noticing that they cannot all join at once.", "Pieces are strongest in sentences, not as single words.", "How can you recognize coordination in a quiet position?", "Your pieces share targets, protect one another, and can switch from one plan to another without losing time.", "pieces", "c3 d2 e4 f3 g2 d5"),

  C("King Safety", "Pawn shield", "Pawns near a castled king deny entry squares. Every pawn move there spends some of that shelter.", "Missing or advanced shield pawns|Enemy pieces aimed at entry squares|Safe retreat squares for the king", "Keep the shield intact unless the move solves a concrete problem or creates needed luft.", "The attacker opens lines with a pawn lever or sacrifice.", "Making a casual pawn move near the king because no tactic exists yet.", "King-pawn moves leave permanent fingerprints.", "Why is h3 or h6 not automatically a useful move?", "It may create luft, but it also weakens squares and can give the opponent a hook for a pawn storm.", "king", "f2 g2 h2 f7 g7 h7 g1 g8"),
  C("King Safety", "Open lines near the king", "An open file or diagonal near a king can turn ordinary pieces into attackers very quickly.", "A missing pawn near the king|Rook or queen aligned with the king|A bishop aimed at the shield", "Close, contest, or evacuate the line before pursuing a distant gain.", "The attacker brings the last piece or uses a sacrifice to remove a defender.", "Counting nearby pieces without tracing the exact open routes.", "King attacks travel on lines.", "Which matters more near a king: the number of attackers or their access?", "Access. Even several pieces are harmless if closed lines prevent them from entering.", "king", "g1 g8 g2 g7 c3 h3 c8"),
  C("King Safety", "Color-complex weakness", "When key pawns leave one color and the matching bishop is absent, squares of that color can become a lasting shelter problem.", "Several weak squares of one color|No bishop to contest them|Enemy queen and bishop able to enter", "Control entry squares, trade the attacking bishop or queen, or move the king away.", "The attacker fixes the pawns and infiltrates on the weak color.", "Trying to defend every weak square individually.", "Defend the entrances, not every tile.", "Why can exchanging a bishop create king-safety problems later?", "The bishop may have been the only piece able to contest important squares of its color around the king.", "king", "f3 g2 h3 f6 g7 h6 g1 g8"),
  C("King Safety", "Key defender", "A king position may depend on one piece that guards an entry square, blocks a file, or enables exchanges.", "One defender covers several threats|Removing it opens a line|The defender is overloaded or pinned", "Preserve, reinforce, or replace the defender before it is exchanged.", "The attacker trades, distracts, or deflects that piece.", "Treating every defending piece as interchangeable.", "Find the piece holding the roof up.", "What should you ask before trading a piece near your own king?", "Which squares, lines, and enemy sacrifices become possible after that defender disappears?","king", "f3 g2 h2 g1 c5 d4"),
  C("King Safety", "Opposite-side castling", "With kings on opposite wings, pawn advances gain tempo because they attack without exposing your own king on that wing.", "Kings on different flanks|Pawn storms can advance with tempo|The center may open suddenly", "Attack quickly, but keep enough control of the center to stop counterplay.", "The opponent races on the other wing or breaks the center first.", "Counting pawns pushed instead of counting open lines and arriving pieces.", "In a race, open lines beat pretty pawn chains.", "What often decides an opposite-side castling attack?", "Move order, speed of line opening, and which side brings more pieces to the king first.", "opposite", "c1 g8 a2 b2 c2 f7 g7 h7"),

  C("Strategic Decisions", "Prophylaxis", "Prophylaxis means asking what the opponent wants and reducing its value without abandoning your own plan.", "A clear enemy break|A piece seeking an outpost|A threat that becomes strong next move", "Choose a move that improves your position while making their plan harder.", "The opponent can switch plans if you over-defend one idea.", "Playing a purely defensive move against a plan that was never dangerous.", "Their best idea belongs in your calculation.", "What is the most useful prophylactic question?", "If I passed, what would my opponent play—and how much would it matter?","strategy", "c5 d4 e5 f4"),
  C("Strategic Decisions", "Favorable exchange", "Every exchange changes the remaining jobs. Trade the piece that enables the opponent's plan, not merely a piece of equal value.", "Their best piece has a unique role|Your bad piece can trade for it|The resulting structure favors you", "Visualize the position after the recapture and compare the remaining pieces.", "The opponent may recapture with a different piece or use the opened line.", "Trading because exchanges feel safe, without evaluating the after-position.", "Do not count what leaves; judge what stays.", "When is bishop for knight positionally sensible?", "When the knight is a crucial blockader, outpost piece, or attacker and the resulting structure favors your remaining pieces.", "strategy", "c3 d5 e3 f6"),
  C("Strategic Decisions", "Simplification", "Simplifying reduces tactical noise, but only helps when the quieter position favors your king, structure, or remaining pieces.", "A material advantage|Enemy counterplay depends on pieces|A favorable pawn ending after trades", "Exchange active enemy pieces while preserving the structure or piece that carries your edge.", "The opponent seeks a pawn ending, fortress, or active rook ending.", "Trading automatically when ahead and entering a drawn or worse ending.", "Simplify the problem, not the advantage.", "You are a pawn up. Should you trade every piece?", "No. Trade counterplay, but check whether the resulting ending preserves a real winning route.", "strategy", "d1 d8 c3 c6 e4 e5"),
  C("Strategic Decisions", "Two weaknesses", "One weakness can often be defended. A second weakness far away stretches the defender until something breaks.", "One fixed target already tied down|Space to switch wings|Defenders with limited mobility", "Fix the first weakness, create the second, then switch before the defense can reorganize.", "The defender seeks activity or trades the attacking pieces.", "Attacking the first weakness forever after the defense is fully arranged.", "Fix one, make another, switch.", "Why should the two weaknesses be far apart?", "Distance makes it difficult for the same king or pieces to defend both in time.", "strategy", "a6 b6 f7 g7 a1 f1"),
  C("Strategic Decisions", "Restriction", "A restrictive move removes useful squares or breaks, often making every later improvement easier.", "One freeing break holds the position together|An enemy piece has only one route|A pawn move can take away key squares", "Limit the opponent's active idea while improving your own least active piece.", "The opponent may accept a weakness to gain freedom.", "Restricting harmless moves while missing a real source of counterplay.", "Take away the move that gives them air.", "How is restriction different from a direct attack?", "Restriction reduces options first; the target often appears only after the opponent becomes passive.", "strategy", "c5 d5 e5 f5 c6 f6"),
  C("Strategic Decisions", "Favorable transformation", "A position can change from one kind of advantage to another: space into an outpost, activity into a pawn, or attack into an ending.", "A break or exchange changes the structure|Your current edge may fade|A new lasting edge can replace it", "Convert a temporary edge into a durable one before the moment passes.", "The opponent tries to force a transformation that sheds the weakness.", "Clinging to the original advantage after the position asks for a new one.", "Advantages change clothes.", "Why trade an active rook for a structural gain?", "If the activity is temporary and the resulting pawn or ending advantage is durable and sufficient.", "strategy", "d4 e5 c5 f4 d7"),
  C("Conversion & Defense", "Converting an advantage", "Conversion is the art of reducing counterplay while making the advantage easier to use.", "A stable edge already exists|The opponent has one active resource|A clear target or entry square", "Stop the active resource, improve all pieces, then make the decisive break.", "The defender seeks tactical complications or a fortress.", "Trying to win immediately and giving the opponent unnecessary chances.", "First make it safe; then make it bigger.", "What is often the first step when converting a positional edge?", "Identify and limit the opponent's counterplay before rushing to cash in the advantage.", "endgame", "d5 e5 c6 f6 a2 h7"),
  C("Conversion & Defense", "Active defense", "The best defense often creates a threat, contests a line, or sacrifices material to gain activity.", "Passive pieces tied to targets|A chance to attack the base|A break that changes the structure", "Give the opponent a problem so they cannot improve without cost.", "The stronger side will neutralize activity before returning to the weakness.", "Defending every pawn and allowing complete paralysis.", "Do not just hold; make them answer.", "Why can giving up a pawn be good defense?", "The sacrifice may activate the king or rook, eliminate a worse weakness, or create counterplay sufficient to draw.", "endgame", "a2 d2 d7 h7 e4 e6"),
  C("Conversion & Defense", "Counterplay", "Counterplay is an active threat elsewhere that forces the stronger side to spend time responding.", "A pawn break on the other wing|An exposed king|A target that can be reached with tempo", "Choose the fastest credible source of activity, even if it concedes something small.", "The opponent wants to restrain the break and return to the main target.", "Starting a slow plan while the opponent's advantage grows without resistance.", "When worse, ask what can become urgent.", "What makes counterplay real rather than hopeful?", "It creates concrete threats or structural changes that the opponent cannot safely ignore.", "endgame", "a4 b5 f4 g5 d1 d8"),
  C("Conversion & Defense", "Fortress thinking", "A fortress is a defensive setup the stronger side cannot penetrate, even with extra material.", "No entry squares|A stable blockade|The attacker cannot create a second weakness", "Trade the attacker's useful pawns, fix the blockading pieces, and avoid unnecessary moves.", "The attacker seeks zugzwang, a pawn break, or a new entry route.", "Assuming material alone guarantees progress.", "No entry, no victory.", "What three features suggest a possible fortress?", "A secure blockade, no viable entry squares, and no pawn break capable of changing the structure.", "endgame", "g1 f2 g3 h2 g8 f7 g7 h7"),
  C("Conversion & Defense", "Zugzwang and reserve tempi", "In quiet endings, the right to move can be a burden. A spare pawn move may preserve the position until the opponent must yield.", "Kings face critical squares|Pieces have no safe waiting move|One side has a spare pawn step", "Count reserve tempi before fixing the pawns and use opposition carefully.", "The opponent may triangulate or save a pawn move of their own.", "Playing a harmless pawn move early and losing the only waiting move later.", "Save one quiet move for the moment that matters.", "What is a reserve tempo?", "A safe waiting move—often a pawn step—kept in reserve to pass the move back at a critical moment.", "endgame", "d4 d6 e3 e5 a2 a7 h2 h7")
];

const lenses = [
  { name: "Notice", label: "Pattern recognition", prefix: "Spot", aim: c => `Slow down and locate the clues: ${c.clues.join("; ").toLowerCase()}.`, question: "What is present?" },
  { name: "Evaluate", label: "Comparison", prefix: "Judge", aim: c => `Compare both sides before choosing a move. ${c.idea}`, question: "Who benefits, and why?" },
  { name: "Plan", label: "Plan building", prefix: "Plan with", aim: c => `Turn the feature into a verb: ${c.plan}`, question: "What should change next?" },
  { name: "Improve", label: "Piece improvement", prefix: "Improve through", aim: c => `Find the least useful piece and connect its route to ${c.title.toLowerCase()}.`, question: "Which piece needs a job?" },
  { name: "Prevent", label: "Prophylaxis", prefix: "Limit", aim: c => `Give the opponent a free move in your mind. ${c.counter}`, question: "What do they want?" },
  { name: "Exchange", label: "Trade decisions", prefix: "Exchange around", aim: c => `Imagine one pair of pieces removed, then ask whether ${c.title.toLowerCase()} becomes stronger or weaker.`, question: "What remains after the trade?" },
  { name: "Candidates", label: "Move generation", prefix: "Find moves for", aim: c => `Generate one improving move, one restrictive move, and one transforming move for ${c.title.toLowerCase()}.`, question: "Which three moves deserve calculation?" },
  { name: "Calculate", label: "Strategic calculation", prefix: "Calculate", aim: c => `Calculate only the lines that can change the positional verdict: captures, breaks, checks, and forced replies.`, question: "Does the position survive contact?" },
  { name: "Play both sides", label: "Attack and defense", prefix: "Play both sides of", aim: c => `State the best plan for each side. Your evaluation is credible only if it survives ${c.counter.toLowerCase()}`, question: "What is the best resistance?" },
  { name: "Master", label: "Integration", prefix: "Use", aim: c => `Apply the idea without turning it into a rigid rule. ${c.idea}`, question: "When does the rule bend?" }
];

if (concepts.length !== 50 || lenses.length !== 10) throw new Error("Curriculum must be 50 concepts × 10 passes.");

